# GCU400 backend implementation of special_modified_bessel_i0 / _out.
#
# History: the generic (KernelGen-generated, CUDA-only) implementation guards
# its host wrappers with `x.is_cuda`, which can never hold for GCU tensors, so
# this vendor override keeps the same A&S polynomial math but a device-agnostic
# check and a grid-strided launch (grid.x never exceeds the 65535 program
# limit of this backend; the full test/benchmark shapes reach 512M elements).
#
# 2026-11-16 perf round (L600 48SP, official bench kernel mode do_bench
# median w1000/r100): the previous BLOCK=32768 / persistent-16-iters config
# ran the division-heavy chain at ~66ns/elem (16.7M fp32: 1186us probe) while
# the sibling `i0` op (BLOCK=4096 / grid<=96) ran the same polynomial at
# 13ns/elem.  Ablation ladder (memcpy 50.9us / poly-with-div 1020us /
# poly+exp+rsqrt-divfree 446us at 16.7M fp32 B32768) pinned the division as
# the dominant slot: on GCU400 the 128-lane `tops_floordivf` vector call has
# no cross-call ILP, and a div+select in the chain costs more than exp+rsqrt
# combined.  The chain is now division-free: r = rsqrt(ax) is computed once
# and reused both for the big-branch argument (yb = 3.75*r*r == 3.75/ax for
# ax > 0) and for the final exp(ax)*p_big*r factor, which also removes the
# safe_ax select.  Lanes with ax == 0 select the small branch (I0(0) = 1)
# and merely produce inf/NaN in the discarded big-branch lanes.
# Retuned config (B4096/nw4 masked GSL loop, grid cap 48 for 2-byte dtypes /
# 96 for fp32, exact next_pow2 tile for tiny sizes) measured at 16.7M:
# fp32 207us / fp16 180us and at 512M: fp32 6.57ms / fp16 5.57ms, versus
# 1111us / 1005us / 33.6ms / 30.9ms for the previous implementation.

import logging

import torch
import triton
import triton.language as tl

import flag_gems
from flag_gems.runtime import torch_device_fn
from flag_gems.utils import libentry

logger = logging.getLogger(__name__)

NUM_SIPS = 24


@triton.jit
def _i0_compute(x):
    """Elementwise modified Bessel I0 for an fp32 vector x (same polynomial
    as the generic KernelGen implementation).  No per-lane guards: dead lanes
    are discarded by the final select."""
    ax = tl.abs(x)
    use_small = ax <= 3.75

    # ---- small region: |x| <= 3.75 ----
    z = ax * (1.0 / 3.75)
    y = z * z

    p_small_inner = tl.fma(y, 0.0045813, 0.0360768)
    p_small_inner = tl.fma(y, p_small_inner, 0.2659732)
    p_small_inner = tl.fma(y, p_small_inner, 1.2067492)
    p_small_inner = tl.fma(y, p_small_inner, 3.0899424)
    p_small_inner = tl.fma(y, p_small_inner, 3.5156229)
    res_small = tl.fma(y, p_small_inner, 1.0)

    # ---- large region: |x| > 3.75 ----
    # One rsqrt serves both the argument (yb = 3.75 * r * r == 3.75 / ax,
    # exact for ax > 0; the big branch is only selected there) and the
    # exp(ax) * p_big / sqrt(ax) factor.  Lanes that will select the small
    # branch may divide by zero here and yield inf/NaN; they are discarded.
    r = tl.rsqrt(ax)
    yb = 3.75 * r * r

    p_big_inner = tl.fma(yb, 0.00392377, -0.01647633)
    p_big_inner = tl.fma(yb, p_big_inner, 0.02635537)
    p_big_inner = tl.fma(yb, p_big_inner, -0.02057706)
    p_big_inner = tl.fma(yb, p_big_inner, 0.00916281)
    p_big_inner = tl.fma(yb, p_big_inner, -0.00157565)
    p_big_inner = tl.fma(yb, p_big_inner, 0.00225319)
    p_big_inner = tl.fma(yb, p_big_inner, 0.01328592)
    p_big = tl.fma(yb, p_big_inner, 0.39894228)

    res_big = tl.exp(ax) * p_big * r

    return tl.where(use_small, res_small, res_big)


@libentry()
@triton.jit(do_not_specialize=["n_elements"])
def special_modified_bessel_i0_kernel(x_ptr, out_ptr, n_elements, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    arange = tl.arange(0, BLOCK)
    num_blocks = (n_elements + BLOCK - 1) // BLOCK
    for block_id in tl.range(pid, num_blocks, nprog):
        offs = block_id * BLOCK + arange
        mask = offs < n_elements
        x = tl.load(x_ptr + offs, mask=mask).to(tl.float32)
        res = _i0_compute(x)
        tl.store(out_ptr + offs, res, mask=mask)


def _choose_launch(n_total, itemsize):
    # Tiny sizes: one exact next_pow2 tile per program keeps the launch
    # ramp minimal; mid/big sizes: B4096/nw4 with a small persistent grid
    # (16-bit loads favor cap48, fp32 favors cap96; ties within ~1%).
    if n_total <= 8192:
        block = max(min(triton.next_power_of_2(n_total), 4096), 64)
        return block, 4, triton.cdiv(n_total, block)
    cap = 48 if itemsize == 2 else 96
    tiles = triton.cdiv(n_total, 4096)
    return 4096, 4, min(tiles, cap)


def _launch(out: torch.Tensor, x: torch.Tensor) -> torch.Tensor:
    assert (
        out.numel() == x.numel()
    ), "Input and output must have the same number of elements"
    assert out.device == x.device, "Input and output must be on the same device"

    # Ensure floating point compute
    if not x.is_floating_point():
        x = x.to(torch.get_default_dtype())

    # Cast input to match the desired output dtype if needed
    # (Compute is done in fp32 inside the kernel; store casts to out dtype)
    if x.dtype != out.dtype:
        x = x.to(out.dtype)

    x_contig = x.contiguous()
    out_was_noncontig = not out.is_contiguous()
    out_contig = out.contiguous() if out_was_noncontig else out

    n_elements = out_contig.numel()
    if n_elements == 0:
        return out

    block, num_warps, grid_size = _choose_launch(n_elements, x_contig.element_size())
    # The external llvm converter intermittently fails on cold compiles
    # (nondeterministic, host-level userland flake windows on shared
    # nodes); retrying the launch recompiles and succeeds (abs.py / neg.py
    # / square.py precedents).
    for attempt in range(3):
        try:
            with torch_device_fn.device(x_contig.device):
                special_modified_bessel_i0_kernel[(grid_size,)](
                    x_contig, out_contig, n_elements, BLOCK=block, num_warps=num_warps
                )
            break
        except Exception as exc:
            if attempt == 2:
                raise
            logger.warning(
                "special_modified_bessel_i0 kernel launch failed (attempt %d): %s",
                attempt + 1,
                exc,
            )

    if out_was_noncontig:
        out.copy_(out_contig)
    return out


def special_modified_bessel_i0(x: torch.Tensor):
    logger.debug("GEMS_ENFLAME SPECIAL_MODIFIED_BESSEL_I0")
    if x.device.type != flag_gems.device:
        raise ValueError(
            f"special_modified_bessel_i0: input tensor must be on {flag_gems.device} device"
        )
    # Result dtype follows PyTorch's floating type behavior
    out_dtype = x.dtype if x.is_floating_point() else torch.get_default_dtype()
    out = torch.empty_like(x, dtype=out_dtype)
    return _launch(out, x)


def special_modified_bessel_i0_out(x: torch.Tensor, out: torch.Tensor):
    logger.debug("GEMS_ENFLAME SPECIAL_MODIFIED_BESSEL_I0_OUT")
    if x.device.type != flag_gems.device or out.device.type != flag_gems.device:
        raise ValueError(
            f"special_modified_bessel_i0_out: input and output tensors must be on {flag_gems.device} device"
        )
    if not out.is_floating_point():
        raise TypeError(
            "special_modified_bessel_i0_out: output tensor must be a floating point type"
        )
    if x.numel() != out.numel():
        raise ValueError(
            "special_modified_bessel_i0_out: input and output must have the same number of elements"
        )
    return _launch(out, x)
